 24→// NewTmuxSession creates a new tmux session running the given command in dir.
 25→// unsetEnv lists environment variable names to strip from the session.
 26→func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
 27→	s := &TmuxSession{name: name}
 28→
 29→	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
 30→	// Build a shell command string, prefixed with env -u for each var to strip.
 31→	// All arguments are shell-quoted to prevent injection or splitting.
 32→	// PATH is always forwarded from the current process so that the freshly-built
 33→	// "entire" binary (prepended to PATH by main_test.go) is available inside the
 34→	// tmux session. Without this, tmux inherits the server's environment which may
 35→	// have an older binary (or none at all).
 36→	var parts []string
 37→	parts = append(parts, "env")
 38→	// Options (-u) must precede variable assignments for BSD env on macOS.
 39→	for _, v := range unsetEnv {
 40→		parts = append(parts, "-u", shellQuote(v))
 41→	}
 42→	parts = append(parts, "PATH="+shellQuote(os.Getenv("PATH")))
 43→	parts = append(parts, shellQuote(command))
 44→	for _, a := range args {
 45→		parts = append(parts, shellQuote(a))
 46→	}
 47→	tmuxArgs = append(tmuxArgs, strings.Join(parts, " "))
 48→
 49→	cmd := exec.Command("tmux", tmuxArgs...)
 50→	if out, err := cmd.CombinedOutput(); err != nil {
 51→		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
 52→	}
 53→	// Keep the pane around after the command exits so we can capture error output.
 54→	setCmd := exec.Command("tmux", "set-option", "-t", name, "remain-on-exit", "on")
 55→	_ = setCmd.Run()
 56→	return s, nil
 57→}
