 59→func (s *TmuxSession) Send(input string) error {
 60→	preSend := stableContent(s.Capture())
 61→	// Send text and Enter separately — Claude's TUI can swallow Enter
 62→	// if it arrives before the input handler finishes processing the text.
 63→	if err := s.SendKeys(input); err != nil {
 64→		return err
 65→	}
 66→	time.Sleep(200 * time.Millisecond)
 67→	if err := s.SendKeys("Enter"); err != nil {
 68→		return err
 69→	}
 70→
 71→	// Wait for the terminal to reflect the echoed input, then snapshot.
 72→	// This ensures WaitFor compares against post-echo content, preventing
 73→	// false matches on prompt characters (e.g. ❯) in the echoed input.
 74→	deadline := time.Now().Add(5 * time.Second)
 75→	for time.Now().Before(deadline) {
 76→		time.Sleep(200 * time.Millisecond)
 77→		current := stableContent(s.Capture())
 78→		if current != preSend {
 79→			s.stableAtSend = current
 80→			return nil
 81→		}
 82→	}
 83→	s.stableAtSend = stableContent(s.Capture())
 84→	return nil
 85→}
