103→// stableContent returns the content with the last few lines stripped,
104→// so that TUI status bar updates don't prevent the settle timer.
105→func stableContent(content string) string {
106→	lines := strings.Split(content, "\n")
107→	if len(lines) > 3 {
108→		lines = lines[:len(lines)-3]
109→	}
110→	return strings.Join(lines, "\n")
111→}
