113→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
114→	re, err := regexp.Compile(pattern)
115→	if err != nil {
116→		return "", fmt.Errorf("invalid pattern: %w", err)
117→	}
118→
119→	deadline := time.Now().Add(timeout)
120→	var matchedAt time.Time
121→	var lastStable string
122→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
123→
124→	for time.Now().Before(deadline) {
125→		content := s.Capture()
126→		stable := stableContent(content)
127→
128→		// Bail early if the process has exited and the pattern doesn't match.
129→		// remain-on-exit keeps the pane alive, so without this check we'd
130→		// poll a dead pane for the full timeout duration.
131→		if !re.MatchString(content) {
132→			if s.IsPaneDead() {
133→				return content, fmt.Errorf("process exited while waiting for %q\n--- pane content ---\n%s\n--- end pane content ---", pattern, content)
134→			}
135→			// Pattern lost — reset
136→			matchedAt = time.Time{}
137→			lastStable = ""
138→			time.Sleep(pollInterval)
139→			continue
140→		}
141→
142→		// Detect content change since Send was called
143→		if !contentChanged && stable != s.stableAtSend {
144→			contentChanged = true
145→		}
146→
147→		if stable != lastStable {
148→			// Pattern matches but content is still changing — reset settle timer
149→			matchedAt = time.Now()
150→			lastStable = stable
151→			time.Sleep(pollInterval)
152→			continue
153→		}
154→
155→		// Pattern matches and content hasn't changed since matchedAt.
156→		// Only settle if content changed at least once after Send
157→		// (prevents false settle on echoed input before agent starts).
158→		if contentChanged && time.Since(matchedAt) >= settleTime {
159→			return content, nil
160→		}
161→
162→		time.Sleep(pollInterval)
163→	}
164→	content := s.Capture()
165→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
166→}
