168→// IsPaneDead returns true if the process inside the tmux pane has exited.
169→// This relies on the remain-on-exit option being set (which NewTmuxSession does).
170→func (s *TmuxSession) IsPaneDead() bool {
171→	cmd := exec.Command("tmux", "display-message", "-t", s.name, "-p", "#{pane_dead}")
172→	out, err := cmd.Output()
173→	if err != nil {
174→		// If tmux itself fails (e.g. session/pane no longer exists),
175→		// treat it as dead so WaitFor doesn't poll until timeout.
176→		return true
177→	}
178→	return strings.TrimSpace(string(out)) == "1"
179→}
