190→	}
191→	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
192→	out, err := cmd.CombinedOutput()
193→	if err != nil {
194→		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
195→	}
196→	return nil
197→}
