 61→	}
 62→
 63→	timeout := 60 * time.Second
 64→	if cfg.PromptTimeout > 0 {
 65→		timeout = cfg.PromptTimeout
 66→	}
 67→	promptCtx, cancel := context.WithTimeout(ctx, timeout)
 68→	defer cancel()
 69→
 70→	args := []string{"-p", prompt, "--model", cfg.Model, "--allow-all"}
 71→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--allow-all"}
 72→	cmd := exec.CommandContext(promptCtx, c.Binary(), args...)
 73→	cmd.Dir = dir
 74→	cmd.Stdin = nil
 75→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
