122→func (c *CopilotCLI) StartSession(ctx context.Context, dir string) (Session, error) {
123→	bin, err := exec.LookPath(c.Binary())
124→	if err != nil {
125→		return nil, fmt.Errorf("agent binary not found: %w", err)
126→	}
127→
128→	// Forward critical env vars into the tmux session. tmux starts a new
129→	// shell that doesn't inherit Go's os.Environ(), so without this the
130→	// session lacks auth tokens (COPILOT_GITHUB_TOKEN) and HOME (for gh auth).
131→	var envArgs []string
132→	for _, key := range []string{"COPILOT_GITHUB_TOKEN", "PATH", "HOME", "TERM"} {
133→		if v := os.Getenv(key); v != "" {
134→			envArgs = append(envArgs, key+"="+v)
135→		}
136→	}
137→	args := append([]string{"env"}, envArgs...)
138→	args = append(args, bin, "--model", "gpt-4.1", "--allow-all")
139→
140→	name := fmt.Sprintf("copilot-test-%d", time.Now().UnixNano())
141→	// Strip CI env vars that may affect interactive mode.
142→	unset := []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}
143→	s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
144→	if err != nil {
145→		return nil, err
146→	}
147→
148→	// Dismiss startup dialogs (folder trust, etc.) then wait for the "❯" prompt.
149→	// Copilot CLI shows a "Confirm folder trust" dialog in interactive mode for
150→	// new directories. "Yes" is pre-selected, so Enter dismisses it.
151→	foundPrompt := false
152→	for range 5 {
153→		content, err := s.WaitFor(`(❯|Enter to select)`, 30*time.Second)
154→		if err != nil {
155→			_ = s.Close()
156→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
157→		}
158→		if strings.Contains(content, "❯") && !strings.Contains(content, "Enter to select") {
159→			foundPrompt = true
160→			break
161→		}
162→		_ = s.SendKeys("Enter")
163→		time.Sleep(500 * time.Millisecond)
164→	}
165→	if !foundPrompt {
166→		_ = s.Close()
167→		return nil, errors.New("copilot CLI did not reach interactive prompt after dismissing startup dialogs")
168→	}
169→	s.stableAtSend = ""
170→
171→	return s, nil
172→}
